import {operatorError} from './operatorError';
import {WebProductModifiers} from './WebProductModifiers';
import {WebProductSellingOptions} from './WebProductSellingOptions';
import {WebInventoryReceiptDialog} from './WebInventoryReceiptDialog';
import {WebMovementReversalDialog} from './WebMovementReversalDialog';
import {inventoryRevisions} from './inventoryRevisions';
import React,{useEffect,useMemo,useState} from 'react';
import {AlertTriangle,ArrowRightLeft,Boxes,PackageCheck,Search} from 'lucide-react';
import {allowed,type BusinessRecord,type WebSession} from './session';
import {parseMoneyToMinor,parseQuantity} from '../../utils/fiscal';
import {calculateRecipeCost,canonicalizeMeasurement} from '../../utils/inventoryUnits';
import {Dialog} from '../../design-system/controls';
import {WebPhysicalCountDialog} from './WebPhysicalCountDialog';
import {WebStockCountHistory} from './WebStockCountHistory';
import {physicalStock,movementPayload} from '../../utils/bottleInventory';
import {SmartItemDialog} from './SmartItemDialog';
import {isCommandConfirmed,type CommandOutcome} from '../../types/transactions';
import {WebActionDialog} from './WebActionDialog';

type CommandFn=(operation:string,collection:string,id:string,payload:Record<string,unknown>)=>Promise<CommandOutcome>;
const field='w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-amber-400';
const button='rounded-lg border border-slate-700 bg-slate-900 px-3 py-2 text-sm font-semibold hover:bg-slate-800 disabled:opacity-40';
const primary='rounded-lg bg-amber-400 px-3 py-2 text-sm font-bold text-slate-950 hover:bg-amber-300 disabled:opacity-40';
const money=(minor:unknown)=>new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES'}).format(Number(minor||0)/100);
const signedMinorInput=(value:unknown)=>{const amount=Number(value||0),absolute=Math.abs(amount);return `${amount<0?'-':''}${Math.floor(absolute/100)}.${String(absolute%100).padStart(2,'0')}`};
const signedValue=(value:unknown,parse:(text:string)=>number)=>{const text=String(value??'').trim();return (text.startsWith('-')?-1:1)*parse(text.startsWith('-')?text.slice(1):text)};
const minorInput=(value:unknown)=>{const amount=Number(value||0);return `${Math.floor(amount/100)}.${String(amount%100).padStart(2,'0')}`};
const data=(record?:BusinessRecord)=>record?.data as Record<string,any>|undefined;
const active=(records:BusinessRecord[],collection:string)=>records.filter(r=>r.collection===collection&&!r.archived);
const archived=(records:BusinessRecord[],collection:string)=>records.filter(r=>r.collection===collection&&r.archived);
const total=(stock:BusinessRecord)=>Object.values(data(stock)?.currentStock||{}).reduce((sum:number,value)=>sum+Number(value||0),0);
const status=(stock:BusinessRecord)=>{const q=total(stock),r=Number(data(stock)?.reorderLevel||0);return q<=0?'OUT':r>0&&q<=r?'LOW':'HEALTHY'};
const tone=(s:string)=>s==='OUT'?'border-rose-500/30 bg-rose-500/10 text-rose-200':s==='LOW'?'border-amber-500/30 bg-amber-500/10 text-amber-200':'border-emerald-500/30 bg-emerald-500/10 text-emerald-200';
const sealedOpenBalance=(stock:BusinessRecord,locationId:string)=>{const d=data(stock)!;const size=Number(d.sealedContainerSize||0);if(d.baseUnit!=='ml'||!Number.isFinite(size)||size<=0)return null;const stored=d.sealedOpenStock?.[locationId];const totalAtLocation=Number(d.currentStock?.[locationId]||0);const sealed=Number.isFinite(Number(stored?.sealedContainers))?Number(stored.sealedContainers):Math.floor(totalAtLocation/size);const open=Number.isFinite(Number(stored?.openQuantity))?Number(stored.openQuantity):Number((totalAtLocation-sealed*size).toFixed(6));if(sealed<0||open<0||open>=size+0.000001||Math.abs(sealed*size+open-totalAtLocation)>0.001)return null;return {sealed,open,size}};
const outcomeMessage=(outcome:CommandOutcome,action='Action')=>{switch(outcome.kind){case'CONFIRMED':return `${action} confirmed and synchronized.`;case'DRAFT_SAVED':return `${action} saved as a draft; it has not taken effect.`;case'PENDING':return `${action} is waiting to synchronize. Do not submit it again.`;case'OUTCOME_UNKNOWN':case'REJECTED':case'CONFLICT':case'BLOCKED':return outcome.message}};

export function WebCatalogView({records,session,disabled,command,closeWhenQueued=false}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn;closeWhenQueued?:boolean}){
 const products=active(records,'products');const stocks=active(records,'stockItems');const locations=active(records,'stockLocations');
 const [kind,setKind]=useState<'PRODUCT'|'STOCK'|'LOCATION'|null>(null);const [editing,setEditing]=useState<BusinessRecord|null>(null);
 const [form,setForm]=useState<Record<string,any>>({});
 const [recipeStockId,setRecipeStockId]=useState('');const [recipeQuantity,setRecipeQuantity]=useState(1);const [recipeUnit,setRecipeUnit]=useState('g');
 const [validationError,setValidationError]=useState('');
 const [commandNotice,setCommandNotice]=useState('');
 const [masterActionRequest,setMasterActionRequest]=useState<{record:BusinessRecord;operation:string;verb:'archive'|'restore'}|null>(null);
 const [smartItemOpen,setSmartItemOpen]=useState(false);
 const canCatalog=allowed(session,'catalog.manage');const canInventory=allowed(session,'inventory.adjust');
 const open=(next:'PRODUCT'|'STOCK'|'LOCATION',record?:BusinessRecord)=>{
  setCommandNotice('');setKind(next);setEditing(record||null);setValidationError('');const d=data(record)||{};
  if(next==='PRODUCT')setForm({...d,modifiers:Array.isArray(d.modifiers)?d.modifiers.map((row:any)=>({...row,priceDeltaText:signedMinorInput(row.priceDeltaMinor)})):[],portions:Array.isArray(d.portions)?d.portions.map((portion:any)=>({...portion,priceText:minorInput(portion.priceMinor)})):[],name:d.name||'',code:d.code||'',price:minorInput(d.priceMinor),category:d.category||'GENERAL',routeTo:d.routeTo||'BAR',stockItemId:Array.isArray(d.recipeIngredients)&&d.recipeIngredients.length? '':d.stockItemId||'',barcode:d.barcode||'',favorite:!!d.favorite,taxClassId:d.taxClassId||'',recipeIngredients:Array.isArray(d.recipeIngredients)?d.recipeIngredients:[]});
  if(next==='STOCK')setForm({name:d.name||'',code:d.code||'',baseUnit:d.baseUnit||'unit',barcode:d.barcode||'',barcodeAliases:Array.isArray(d.barcodeAliases)?d.barcodeAliases:[],purchasePackages:Array.isArray(d.purchasePackages)?d.purchasePackages.map((pack:any)=>({...pack,unitCostText:minorInput(pack.unitCostMinor)})):[],scanUnitQuantity:Number(d.scanUnitQuantity||1),reorderLevel:Number(d.reorderLevel||0),averageUnitCost:Number(d.averageUnitCostMinor||0)/100,sealedContainerSize:Number(d.sealedContainerSize||0)});
  if(next==='LOCATION')setForm({name:d.name||'',code:d.code||'',type:d.type||'STORE'});
 };
 const save=async()=>{
  setValidationError('');
  const id=editing?.id||crypto.randomUUID();
  let outcome:CommandOutcome|undefined;
  if(kind==='PRODUCT'){try{
   const options={modifiers:(form.modifiers||[]).map((row:any)=>({id:row.id,name:row.name,priceDeltaMinor:signedValue(row.priceDeltaText,parseMoneyToMinor),ingredientAdjustments:(row.ingredientAdjustments||[]).map((item:any)=>({stockItemId:item.stockItemId,quantityDelta:signedValue(item.quantityDelta,text=>parseQuantity(text,{min:Number.MIN_VALUE,max:1_000_000_000,maxDecimals:6}))}))})),inventoryType:form.inventoryType||'STANDARD',sellingMode:form.sellingMode||undefined,portionVolume:form.portionVolume!==undefined&&form.portionVolume!==null&&form.portionVolume!==''?parseQuantity(form.portionVolume,{min:Number.MIN_VALUE,maxDecimals:6}):undefined,recipeYield:form.recipeYield!==undefined&&form.recipeYield!==null&&form.recipeYield!==''?parseQuantity(form.recipeYield,{min:1,max:100000,integer:true}):undefined,portions:(form.portions||[]).map((portion:any)=>({id:portion.id,name:String(portion.name||'').trim(),priceMinor:parseMoneyToMinor(portion.priceText),volume:parseQuantity(portion.volume,{min:Number.MIN_VALUE,maxDecimals:6}),wholeContainerSale:portion.wholeContainerSale===true})),outletIds:form.outletIds||[]};
   outcome=await command('product.save','products',id,{id,expectedVersions:[{collection:'products',id,version:editing?.version??0}],data:{...options,name:String(form.name||'').trim(),code:String(form.code||'').trim(),priceMinor:parseMoneyToMinor(form.price||'0'),category:String(form.category||'GENERAL').trim(),routeTo:String(form.routeTo||'BAR'),stockItemId:String(form.stockItemId||'').trim()||undefined,barcode:String(form.barcode||'').trim()||undefined,favorite:!!form.favorite,taxClassId:String(form.taxClassId||''),recipeIngredients:Array.isArray(form.recipeIngredients)?form.recipeIngredients:[]}});
  }catch(error){setValidationError(error instanceof Error?error.message:'Review product selling options.');return}}
  if(kind==='STOCK'){try{const scanUnitQuantity=parseQuantity(form.scanUnitQuantity,{min:Number.MIN_VALUE});const reorderLevel=parseQuantity(form.reorderLevel);const sealedContainerSize=form.sealedContainerSize?parseQuantity(form.sealedContainerSize,{min:Number.MIN_VALUE}):undefined;const purchasePackages=(Array.isArray(form.purchasePackages)?form.purchasePackages:[]).map((pack:any)=>{const cost=String(pack.unitCostText??'').trim();if(!cost)throw new Error('Enter a purchase package cost; enter zero for a free package.');return{id:pack.id||crypto.randomUUID(),name:String(pack.name||'').trim(),baseQuantity:parseQuantity(pack.baseQuantity,{min:Number.MIN_VALUE}),unitCostMinor:parseMoneyToMinor(cost),barcode:String(pack.barcode||'').trim()||undefined}});if(purchasePackages.some((pack:any)=>!pack.name))throw new Error('Give every purchase package a name.');outcome=await command('stockItem.save','stockItems',id,{id,data:{name:String(form.name||'').trim(),code:String(form.code||'').trim(),baseUnit:String(form.baseUnit||'unit').trim(),barcode:String(form.barcode||'').trim()||undefined,barcodeAliases:Array.isArray(form.barcodeAliases)?form.barcodeAliases.filter((value:any)=>typeof value==='string'&&value.trim()).map((value:string)=>value.trim()):[],purchasePackages,scanUnitQuantity,reorderLevel,averageUnitCostMinor:Number(form.averageUnitCost||0)*100,...(sealedContainerSize?{sealedContainerSize}:{})}})}catch(error){setValidationError(error instanceof Error?error.message:'Enter valid quantity and package values.');return}}
  if(kind==='LOCATION')outcome=await command('stockLocation.save','stockLocations',id,{id,data:{name:String(form.name||'').trim(),code:String(form.code||'').trim(),type:String(form.type||'STORE')}});
  if((outcome?.kind==='PENDING'||outcome?.kind==='OUTCOME_UNKNOWN')&&closeWhenQueued){setCommandNotice(outcomeMessage(outcome,'Catalog save'));setKind(null);setEditing(null);return}
  if(!outcome||!isCommandConfirmed(outcome)){setValidationError(outcome?outcomeMessage(outcome,'Catalog save'):'Choose a catalog record type before saving.');return}
  setKind(null);setEditing(null);
 };
 const masterAction=async(record:BusinessRecord,op:string)=>{setCommandNotice('');setMasterActionRequest({record,operation:op,verb:op.endsWith('.archive')?'archive':'restore'})};
 const addRecipeIngredient=()=>{const stock=stocks.find(item=>item.id===recipeStockId);if(!stock)return;const baseUnit=String(data(stock)?.baseUnit||'piece').toLowerCase();const mode=baseUnit==='g'||baseUnit==='kg'?'WEIGHT':baseUnit==='ml'||baseUnit==='l'?'VOLUME':'COUNT';try{const entered=canonicalizeMeasurement(recipeQuantity,recipeUnit,mode);const base=canonicalizeMeasurement(1,baseUnit,mode);const quantity=Number((entered.quantity/base.quantity).toFixed(6));if(!Number.isFinite(quantity)||quantity<=0)throw new Error('Enter a positive compatible quantity.');setForm((previous:any)=>({...previous,stockItemId:'',recipeIngredients:[...(previous.recipeIngredients||[]),{stockItemId:recipeStockId,quantity,tracked:true}]}));setRecipeStockId('');setRecipeQuantity(1);setValidationError('')}catch{setValidationError(`Enter a valid ${recipeUnit} amount compatible with ${baseUnit}.`)}};
 const recipeStock=stocks.find(item=>item.id===recipeStockId);const recipeBase=String(data(recipeStock)?.baseUnit||'piece').toLowerCase();const recipeUnits=recipeBase==='g'||recipeBase==='kg'?['g','kg']:recipeBase==='ml'||recipeBase==='l'?['ml','l']:[recipeBase];
 const recipeCostMinor=(()=>{try{return calculateRecipeCost((form.recipeIngredients||[]).map((line:any)=>({quantity:Number(line.quantity),averageCostMinor:Number(data(stocks.find(item=>item.id===line.stockItemId))?.averageUnitCostMinor||0)})))}catch{return Number.NaN}})();
 return <section className="space-y-5">
   <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-xl font-bold">Items and stock</h2><p className="mt-1 text-sm text-slate-400">Add the items you sell and the stock you keep. Change quantities from Stock, not from this list.</p></div><div className="flex flex-wrap gap-2">{(canInventory||canCatalog&&allowed(session,'inventory.view'))&&<button disabled={disabled} className={primary} onClick={()=>setSmartItemOpen(true)}>Smart item setup</button>}{canCatalog&&<><button disabled={disabled} className={button} onClick={()=>open('PRODUCT')}>New product</button><button disabled={disabled} className={button} onClick={()=>open('STOCK')}>New stock item</button></>}{canInventory&&<button disabled={disabled} className={button} onClick={()=>open('LOCATION')}>New stock location</button>}</div></div>
  {commandNotice&&!kind&&!smartItemOpen&&<p role="status" className="rounded-lg border border-slate-700 bg-slate-900 p-3 text-sm">{commandNotice}</p>}
  <div className="grid gap-4 xl:grid-cols-2">
   <Panel title={`Products · ${products.length}`}>{products.map(r=>{const d=data(r)!;return <article key={r.id} className="rounded-xl border border-slate-800 bg-slate-950 p-3"><div className="flex items-start justify-between gap-3"><div><b>{String(d.name)}</b><div className="font-mono text-[11px] text-slate-500">{String(d.code)}</div></div><span className="font-semibold text-amber-300">{money(d.priceMinor)}</span></div><div className="mt-1 text-xs text-slate-500">{String(d.category||'GENERAL')} · {String(d.routeTo||'BAR')}{d.stockItemId?' · stock linked':''}</div>{canCatalog&&<div className="mt-3 flex gap-2"><button disabled={disabled} className={button} onClick={()=>open('PRODUCT',r)}>Edit</button><button disabled={disabled} className={button} onClick={()=>void masterAction(r,'product.archive')}>Archive</button></div>}</article>})}</Panel>
   <Panel title={`Stock masters · ${stocks.length}`}>{stocks.map(r=>{const d=data(r)!;return <article key={r.id} className="rounded-xl border border-slate-800 bg-slate-950 p-3"><div className="flex items-start justify-between gap-3"><div><b>{String(d.name)}</b><div className="font-mono text-[11px] text-slate-500">{String(d.code)}</div></div><span>{total(r).toLocaleString()} {String(d.baseUnit||'units')}</span></div><div className="mt-1 text-xs text-slate-500">Reorder at {Number(d.reorderLevel||0).toLocaleString()} · Avg cost {money(d.averageUnitCostMinor)}</div>{canCatalog&&<div className="mt-3 flex gap-2"><button disabled={disabled} className={button} onClick={()=>open('STOCK',r)}>Edit</button><button disabled={disabled} className={button} onClick={()=>void masterAction(r,'stockItem.archive')}>Archive</button></div>}</article>})}</Panel>
  </div>
  <Panel title={`Stock locations · ${locations.length}`}><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{locations.map(r=>{const d=data(r)!;return <article key={r.id} className="rounded-xl border border-slate-800 bg-slate-950 p-3"><b>{String(d.name)}</b><div className="text-xs text-slate-500">{String(d.code||r.id)} · {String(d.type||'STORE')}</div>{canInventory&&<div className="mt-3 flex gap-2"><button disabled={disabled} className={button} onClick={()=>open('LOCATION',r)}>Edit</button><button disabled={disabled} className={button} onClick={()=>void masterAction(r,'stockLocation.archive')}>Archive</button></div>}</article>})}</div></Panel>
  {(canCatalog&&(archived(records,'products').length+archived(records,'stockItems').length)>0||canInventory&&archived(records,'stockLocations').length>0)&&<details className="rounded-xl border border-slate-800 bg-slate-900 p-3"><summary className="cursor-pointer font-semibold">Archived masters</summary><div className="mt-3 space-y-2">{canCatalog&&archived(records,'products').map(r=><Restore key={r.id} record={r} label={String(data(r)?.name||r.id)} disabled={disabled} onRestore={()=>masterAction(r,'product.reactivate')}/>)}{canCatalog&&archived(records,'stockItems').map(r=><Restore key={r.id} record={r} label={String(data(r)?.name||r.id)} disabled={disabled} onRestore={()=>masterAction(r,'stockItem.reactivate')}/>)}{canInventory&&archived(records,'stockLocations').map(r=><Restore key={r.id} record={r} label={String(data(r)?.name||r.id)} disabled={disabled} onRestore={()=>masterAction(r,'stockLocation.reactivate')}/>)}</div></details>}
  {smartItemOpen&&<SmartItemDialog records={records} session={session} disabled={disabled} command={command} onClose={()=>setSmartItemOpen(false)}/>}
  {masterActionRequest&&<WebActionDialog title={`${masterActionRequest.verb==='archive'?'Archive':'Reactivate'} ${String(data(masterActionRequest.record)?.name||masterActionRequest.record.id)}?`} description={`Record a reason before you ${masterActionRequest.verb} this ${masterActionRequest.record.collection==='products'?'product':masterActionRequest.record.collection==='stockItems'?'stock item':'stock location'}.`} fields={[{name:'reason',label:'Reason',minLength:3,maxLength:500}]} confirmLabel={masterActionRequest.verb==='archive'?'Archive record':'Reactivate record'} danger={masterActionRequest.verb==='archive'} disabled={disabled} onClose={()=>setMasterActionRequest(null)} onConfirm={async values=>{const request=masterActionRequest;const outcome=await command(request.operation,request.record.collection,request.record.id,{id:request.record.id,reason:values.reason.trim()});setCommandNotice(outcomeMessage(outcome,'Catalog action'))}}/>}
  {kind&&<Modal title={editing?`Edit ${kind.toLowerCase()}`:`New ${kind.toLowerCase()}`} onClose={()=>setKind(null)}><div className="space-y-3">
   <label className="block text-sm">Name<input className={field} value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></label>
   <label className="block text-sm">Code / SKU<input className={field} value={form.code||''} onChange={e=>setForm({...form,code:e.target.value})}/></label>
   {kind==='PRODUCT'&&<><label className="block text-sm">Price (KES)<input type="number" min="0" step="0.01" className={field} value={form.price??0} onChange={e=>setForm({...form,price:e.target.value})}/></label><label className="block text-sm">Category<input className={field} value={form.category||''} onChange={e=>setForm({...form,category:e.target.value})}/></label><label className="block text-sm">Route<select className={field} value={form.routeTo||'BAR'} onChange={e=>setForm({...form,routeTo:e.target.value})}><option>BAR</option><option>KITCHEN</option><option>SERVICE</option></select></label><label className="block text-sm">Tax class<select required className={field} value={form.taxClassId||''} onChange={e=>setForm({...form,taxClassId:e.target.value})}><option value="">Select tax class…</option><option value="A_16">Standard · 16%</option><option value="B_0">Zero-rated · 0%</option><option value="C_EXEMPT">Exempt</option></select></label><label className="block text-sm">Linked stock item<select className={field} value={form.stockItemId||''} onChange={e=>setForm({...form,stockItemId:e.target.value})}><option value="">Untracked / later recipe</option>{stocks.map(s=><option key={s.id} value={s.id}>{String(data(s)?.name)}</option>)}</select></label><label className="block text-sm">Barcode<input className={field} value={form.barcode||''} onChange={e=>setForm({...form,barcode:e.target.value})}/></label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={!!form.favorite} onChange={e=>setForm({...form,favorite:e.target.checked})}/>Favorite</label></>}
   {kind==='PRODUCT'&&<section className="space-y-3 rounded-lg border border-slate-800 p-3"><div><b>Recipe ingredients</b><p className="text-xs text-slate-400">Enter kitchen units; ServOS converts to each ingredient's stock unit. POS will deduct these quantities when the order is fired.</p></div><div className="grid gap-2 sm:grid-cols-[1fr_100px_90px_auto]"><select aria-label="Recipe stock ingredient" className={field} value={recipeStockId} onChange={event=>{const id=event.target.value;setRecipeStockId(id);const stock=stocks.find(item=>item.id===id);const unit=String(data(stock)?.baseUnit||'piece').toLowerCase();setRecipeUnit(unit==='kg'?'kg':unit==='l'?'l':unit==='g'?'g':unit==='ml'?'ml':'piece')}}><option value="">Choose ingredient stock</option>{stocks.filter(item=>!(form.recipeIngredients||[]).some((line:any)=>line.stockItemId===item.id)).map(item=><option key={item.id} value={item.id}>{String(data(item)?.name)} · {String(data(item)?.baseUnit||'piece')}</option>)}</select><input aria-label="Recipe ingredient quantity" type="number" min="0.000001" step="any" className={field} value={recipeQuantity} onChange={event=>setRecipeQuantity(Number(event.target.value))}/><select aria-label="Recipe amount unit" className={field} value={recipeUnit} onChange={event=>setRecipeUnit(event.target.value)}>{recipeUnits.map(unit=><option key={unit} value={unit}>{unit}</option>)}</select><button type="button" className={button} disabled={!recipeStockId||!Number.isFinite(recipeQuantity)||recipeQuantity<=0} onClick={addRecipeIngredient}>Add</button></div>{Array.isArray(form.recipeIngredients)&&form.recipeIngredients.map((line:any)=><div key={line.stockItemId} className="flex items-center justify-between rounded bg-slate-950 p-2 text-sm"><span>{String(data(stocks.find(item=>item.id===line.stockItemId))?.name||line.stockItemId)} · {line.quantity} {String(data(stocks.find(item=>item.id===line.stockItemId))?.baseUnit||'piece')}</span><button type="button" className="text-rose-300" onClick={()=>setForm({...form,recipeIngredients:form.recipeIngredients.filter((item:any)=>item.stockItemId!==line.stockItemId)})}>Remove</button></div>)}</section>}
   {kind==='PRODUCT'&&<WebProductModifiers value={form.modifiers||[]} onChange={modifiers=>setForm({...form,modifiers})} stocks={stocks} disabled={disabled}/>}
   {kind==='PRODUCT'&&<WebProductSellingOptions form={form} onChange={setForm} outlets={active(records,'outlets')} disabled={disabled}/>}
   {kind==='STOCK'&&<><label className="block text-sm">Base unit<input className={field} value={form.baseUnit||''} onChange={e=>setForm({...form,baseUnit:e.target.value})}/></label><label className="block text-sm">Barcode<input className={field} value={form.barcode||''} onChange={e=>setForm({...form,barcode:e.target.value})}/></label><label className="block text-sm">Additional barcode aliases, one per line<textarea className={field} rows={3} value={(form.barcodeAliases||[]).join('\n')} onChange={event=>setForm({...form,barcodeAliases:event.target.value.split(/\r?\n/u).map(value=>value.trim()).filter(Boolean)})}/></label><label className="block text-sm">Quantity represented by one scan<input type="number" min="0.000001" step="0.001" className={field} value={form.scanUnitQuantity??1} onChange={e=>setForm({...form,scanUnitQuantity:Number(e.target.value)})}/></label><label className="block text-sm">Reorder level<input type="number" min="0" step="0.001" className={field} value={form.reorderLevel??0} onChange={e=>setForm({...form,reorderLevel:Number(e.target.value)})}/></label><label className="block text-sm">Average unit cost (KES)<input type="number" min="0" step="0.01" className={field} value={form.averageUnitCost??0} onChange={e=>setForm({...form,averageUnitCost:Number(e.target.value)})}/><span className="text-xs text-slate-500">Once stock exists, average cost changes must come through Procurement.</span></label><fieldset className="space-y-3 rounded border border-slate-800 p-3"><legend>Purchase packages</legend><p className="text-xs text-slate-400">Set package quantity in base units. Receiving converts whole packages into the same stock balance.</p>{(form.purchasePackages||[]).map((pack:any,index:number)=><section key={pack.id||index} className="grid gap-2 rounded bg-slate-950 p-2 sm:grid-cols-2"><label className="block text-sm">Package {index+1} name<input required maxLength={100} className={field} value={pack.name||''} onChange={event=>setForm({...form,purchasePackages:form.purchasePackages.map((item:any,i:number)=>i===index?{...item,name:event.target.value}:item)})}/></label><label className="block text-sm">Base quantity<input required type="number" min="0.000001" step="any" className={field} value={pack.baseQuantity??''} onChange={event=>setForm({...form,purchasePackages:form.purchasePackages.map((item:any,i:number)=>i===index?{...item,baseQuantity:event.target.value}:item)})}/></label><label className="block text-sm">Package cost (KES)<input required inputMode="decimal" className={field} value={pack.unitCostText??'0.00'} onChange={event=>setForm({...form,purchasePackages:form.purchasePackages.map((item:any,i:number)=>i===index?{...item,unitCostText:event.target.value}:item)})}/></label><label className="block text-sm">Package barcode<input className={field} value={pack.barcode||''} onChange={event=>setForm({...form,purchasePackages:form.purchasePackages.map((item:any,i:number)=>i===index?{...item,barcode:event.target.value}:item)})}/></label><button type="button" className="justify-self-start text-sm text-rose-300" onClick={()=>setForm({...form,purchasePackages:form.purchasePackages.filter((_:any,i:number)=>i!==index)})}>Remove package {index+1}</button></section>)}<button type="button" className={button} disabled={(form.purchasePackages||[]).length>=50} onClick={()=>setForm({...form,purchasePackages:[...(form.purchasePackages||[]),{id:crypto.randomUUID(),name:'',baseQuantity:'',unitCostText:'0.00',barcode:''}]})}>Add purchase package</button></fieldset></>}
   {kind==='STOCK'&&form.baseUnit==='ml'&&<label className="block text-sm">Sealed bottle/container size (ml)<input type="number" min="0" step="0.1" className={field} value={form.sealedContainerSize||''} onChange={e=>setForm({...form,sealedContainerSize:e.target.value===''?0:Number(e.target.value)})}/><span className="text-xs text-slate-500">Optional. Enables sealed/open tracking; the size cannot change while stock remains.</span></label>}
   {kind==='LOCATION'&&<label className="block text-sm">Type<select className={field} value={form.type||'STORE'} onChange={e=>setForm({...form,type:e.target.value})}><option>STORE</option><option>FRIDGE</option><option>BAR</option><option>KITCHEN</option><option>OTHER</option></select></label>}
   {kind==='PRODUCT'&&Array.isArray(form.recipeIngredients)&&form.recipeIngredients.length>0&&<p className="rounded-lg bg-slate-950 p-3 text-sm">Calculated recipe cost per sale: <b>{Number.isFinite(recipeCostMinor)?money(recipeCostMinor):'Review ingredient stock costs and quantities'}</b></p>}
   {validationError&&<p className="rounded-lg border border-rose-700/50 bg-rose-500/10 p-2 text-sm text-rose-200">{validationError}</p>}<div className="flex gap-2"><button disabled={disabled||!String(form.name||'').trim()||!String(form.code||'').trim()} className={primary} onClick={()=>void save()}>Save</button><button className={button} onClick={()=>setKind(null)}>Cancel</button></div>
  </div></Modal>}
 </section>;
}

export function WebInventoryView({records,session,disabled,command}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn}){
 const stocks=active(records,'stockItems');const products=active(records,'products');const locations=active(records,'stockLocations');const movements=active(records,'stockMovements').slice().sort((a,b)=>String(data(b)?.occurredAt||'').localeCompare(String(data(a)?.occurredAt||'')));
  const [search,setSearch]=useState('');const [state,setState]=useState('ALL');const [location,setLocation]=useState('ALL');const [selectedId,setSelectedId]=useState(stocks[0]?.id||'');
  const [receiptDialog,setReceiptDialog]=useState<'RECEIVE'|'POLICY'|null>(null);
  const [reversing,setReversing]=useState<BusinessRecord|null>(null);
  const [physicalCount,setPhysicalCount]=useState<{scope:'FULL'|'SELECTED';locationId:string}|null>(null);
  const [modal,setModal]=useState<'ADJUST'|'TRANSFER'|'WASTE'|null>(null);const [batchOpen,setBatchOpen]=useState(false);const [form,setForm]=useState<Record<string,any>>({stockItemId:stocks[0]?.id||'',locationId:locations[0]?.id||'',toLocationId:locations[1]?.id||'',countedQty:0,quantity:1,disposition:'SEALED',reason:''});
const [commandNotice,setCommandNotice]=useState('');
 const selected=stocks.find(s=>s.id===selectedId)||stocks[0];
 const rows=useMemo(()=>stocks.map(stock=>({stock,total:total(stock),status:status(stock)})).filter(row=>{const d=data(row.stock)!;const q=search.trim().toLowerCase();return (!q||[d.name,d.code,d.barcode].some(v=>String(v||'').toLowerCase().includes(q)))&&(state==='ALL'||row.status===state)}),[stocks,search,state]);
 const stockValue=stocks.reduce((sum,s)=>sum+total(s)*Number(data(s)?.averageUnitCostMinor||0),0);
  const [reviewedInventoryRecords,setReviewedInventoryRecords]=useState<BusinessRecord[]>([]);
  const canCount=allowed(session,'inventory.count');const canCorrect=allowed(session,'inventory.adjust');const canBatch=canCorrect;const canReverseMovement=canCorrect;const canTransfer=allowed(session,'inventory.transfer');const canWaste=allowed(session,'inventory.waste');
  const open=(kind:'ADJUST'|'TRANSFER'|'WASTE',stock?:BusinessRecord,loc?:string)=>{
    setCommandNotice('');
    const target=stock||selected||stocks[0];
    const locationId=loc||locations[0]?.id||'';
    setReviewedInventoryRecords(records);
    const balance=target?sealedOpenBalance(target,locationId):null;
    const quantity=Number(data(target)?.currentStock?.[locationId]||0);
    setForm({stockItemId:target?.id||'',locationId,toLocationId:locations.find(item=>item.id!==locationId)?.id||'',countedQty:quantity,expectedQuantity:quantity,expectedBaseUnit:String(data(target)?.baseUnit||''),expectedSealedContainerSize:Number(data(target)?.sealedContainerSize||0),expectedSealedContainers:balance?.sealed??null,expectedOpenQuantity:balance?.open??null,sealedContainers:balance?.sealed??0,openQuantity:balance?.open??0,quantity:1,disposition:'SEALED',reason:''});
    setSelectedId(target?.id||'');
    setModal(kind);
  };

 const commitAdjustment=async()=>{const id=form.stockItemId;let countedQty:number;try{countedQty=adjustmentBreakdownRequired?parseQuantity(Number(form.sealedContainers)*adjustmentSize+Number(form.openQuantity)):parseQuantity(form.countedQty)}catch{return}const outcome=await command('inventory.adjust','stockItems',id,{id,stockItemId:id,locationId:form.locationId,...inventoryRevisions(reviewedInventoryRecords,[id],[form.locationId]),expectedQuantity:Number(form.expectedQuantity),expectedBaseUnit:String(form.expectedBaseUnit||''),expectedSealedContainerSize:Number(form.expectedSealedContainerSize||0),...(adjustmentBreakdownRequired?{expectedSealedContainers:Number(form.expectedSealedContainers),expectedOpenQuantity:Number(form.expectedOpenQuantity),sealedContainers:Number(form.sealedContainers),openQuantity:Number(form.openQuantity)}:{}),countedQty,reason:String(form.reason||'').trim()});setCommandNotice(outcomeMessage(outcome,'Stock correction'));if(isCommandConfirmed(outcome))setModal(null)};
 const commit=async()=>{
  const id=form.stockItemId;
  let quantity:number;
  try{quantity=parseQuantity(form.quantity,{min:Number.MIN_VALUE})}catch{return}
  const operation=modal==='TRANSFER'?'inventory.transfer':'inventory.waste';
  const outcome=await command(operation,'stockItems',id,{id,stockItemId:id,locationId:form.locationId,...inventoryRevisions(reviewedInventoryRecords,[id],modal==='TRANSFER'?[form.locationId,form.toLocationId]:[form.locationId]),...(modal==='TRANSFER'?{toLocationId:form.toLocationId}:{}),...movementPayload({...data(stocks.find(stock=>stock.id===id)),id},form.disposition||'SEALED',String(quantity),form.reason)});
  setCommandNotice(outcomeMessage(outcome,'Inventory action'));
  if(isCommandConfirmed(outcome))setModal(null);
 };

 const selectedData=data(selected);
 const recent=selected?movements.filter(m=>data(m)?.stockItemId===selected.id).slice(0,12):[];

 const adjustmentStock=stocks.find(stock=>stock.id===form.stockItemId);const adjustmentSize=Number(data(adjustmentStock)?.sealedContainerSize||0);const adjustmentSealedBalance=adjustmentStock&&Number.isFinite(Number(form.expectedSealedContainers))&&Number.isFinite(Number(form.expectedOpenQuantity))?{sealed:Number(form.expectedSealedContainers),open:Number(form.expectedOpenQuantity)}:null;const adjustmentBreakdownRequired=modal==='ADJUST'&&adjustmentSize>0;const adjustmentBreakdownInvalid=adjustmentBreakdownRequired&&(!adjustmentSealedBalance||!Number.isInteger(Number(form.sealedContainers))||Number(form.sealedContainers)<0||!Number.isFinite(Number(form.openQuantity))||Number(form.openQuantity)<0||Number(form.openQuantity)>=adjustmentSize);
 return <section className="space-y-5">
  <div className="flex flex-wrap gap-2">{allowed(session,'inventory.receive')&&<button disabled={disabled} className={primary} onClick={()=>setReceiptDialog('RECEIVE')}>Receive stock</button>}{allowed(session,'business.configure')&&<button disabled={disabled} className={button} onClick={()=>setReceiptDialog('POLICY')}>Receiving policy</button>}</div>
  {receiptDialog&&<Modal title={receiptDialog==='POLICY'?'Receiving policy':'Receive stock'} onClose={()=>setReceiptDialog(null)}><WebInventoryReceiptDialog records={records} businessId={session.businessId} policyEditor={receiptDialog==='POLICY'} command={command} onClose={()=>setReceiptDialog(null)}/></Modal>}
    <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-xl font-bold">Stock</h2><p className="mt-1 text-sm text-slate-400">Review stock, record counts, transfers, and waste.</p><p className="mt-1 text-xs text-slate-400">Transfers and waste require an active connection; batch preparation requires an active connection; corrections require a reason and current balance.</p></div><div className="flex flex-wrap gap-2">{canBatch&&<button disabled={disabled} className={button} onClick={()=>{setCommandNotice('');setBatchOpen(true)}}>Prepare batch</button>}{canCount&&<button data-guide-anchor="inventory.count" disabled={disabled} className={primary} onClick={()=>setPhysicalCount({scope:'FULL',locationId:''})}>Count stock</button>}{canCount&&<button disabled={disabled} className={button} onClick={()=>setPhysicalCount({scope:'SELECTED',locationId:''})}>Quick count</button>}{canCorrect&&<button disabled={disabled||!selected} className={button} onClick={()=>open('ADJUST',selected)}>Correct selected stock</button>}{canTransfer&&<button disabled={disabled} className={button} onClick={()=>open('TRANSFER')}>Transfer</button>}{canWaste&&<button disabled={disabled} className={button} onClick={()=>open('WASTE')}>Waste</button>}</div></div>
  {commandNotice&&<p role="status" className="rounded-lg border border-slate-700 bg-slate-900 p-3 text-sm">{commandNotice}</p>}
  <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={<Boxes className="h-4 w-4"/>} label="Stock masters" value={String(stocks.length)}/><Metric icon={<PackageCheck className="h-4 w-4"/>} label="Stock value" value={money(stockValue)}/><Metric icon={<AlertTriangle className="h-4 w-4"/>} label="Low stock" value={String(stocks.filter(s=>status(s)==='LOW').length)}/><Metric icon={<AlertTriangle className="h-4 w-4"/>} label="Out of stock" value={String(stocks.filter(s=>status(s)==='OUT').length)}/></div>
  <div className="grid gap-2 md:grid-cols-[1fr_180px_220px]"><label className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-500"/><input className={field+' pl-9'} value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search stock name, SKU or barcode"/></label><select className={field} value={state} onChange={e=>setState(e.target.value)}><option value="ALL">All stock states</option><option>HEALTHY</option><option>LOW</option><option>OUT</option></select><select className={field} value={location} onChange={e=>setLocation(e.target.value)}><option value="ALL">All locations / total</option>{locations.map(l=><option key={l.id} value={l.id}>{String(data(l)?.name)}</option>)}</select></div>
  <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]"><div className="overflow-x-auto rounded-xl border border-slate-800"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-slate-900 text-xs uppercase text-slate-500"><tr><th className="p-3">Stock item</th><th className="p-3">State</th><th className="p-3 text-right">On hand</th><th className="p-3 text-right">Reorder</th><th className="p-3 text-right">Value</th></tr></thead><tbody>{rows.map(({stock,total:qty,status:st})=>{const d=data(stock)!;const shown=location==='ALL'?qty:Number(d.currentStock?.[location]||0);return <tr key={stock.id} onClick={()=>setSelectedId(stock.id)} className="cursor-pointer border-t border-slate-800 hover:bg-slate-900"><td className="p-3"><b>{String(d.name)}</b><div className="font-mono text-[11px] text-slate-500">{String(d.code)}</div></td><td className="p-3"><span className={`rounded-full border px-2 py-1 text-[10px] font-black ${tone(st)}`}>{st}</span></td><td className="p-3 text-right font-mono">{physicalStock({...d,id:stock.id},location==='ALL'?undefined:location)}<small className="block text-slate-500">{shown.toLocaleString()} {String(d.baseUnit||'')}</small></td><td className="p-3 text-right">{Number(d.reorderLevel||0).toLocaleString()}</td><td className="p-3 text-right">{money(qty*Number(d.averageUnitCostMinor||0))}</td></tr>})}</tbody></table></div>
   <aside className="rounded-xl border border-slate-800 bg-slate-900 p-4">{selected&&selectedData?<><div className="flex items-start justify-between"><div><div className="text-xs uppercase text-slate-500">Selected stock</div><h3 className="text-lg font-bold">{String(selectedData.name)}</h3></div><span className={`rounded-full border px-2 py-1 text-[10px] font-black ${tone(status(selected))}`}>{status(selected)}</span></div><div className="mt-4 space-y-2">{locations.map(l=>{const balance=sealedOpenBalance(selected,l.id);return <button key={l.id} disabled={!canCount||disabled} onClick={()=>setPhysicalCount({scope:'FULL',locationId:l.id})} className="flex w-full items-center justify-between rounded-lg border border-slate-800 bg-slate-950 p-3 text-left"><span>{String(data(l)?.name)}{balance&&<span className="mt-1 block text-xs text-slate-400">{balance.sealed} sealed · {balance.open.toLocaleString()} ml open</span>}</span><span className="text-right font-mono">{Number(selectedData.currentStock?.[l.id]||0).toLocaleString()} {String(selectedData.baseUnit||'')}</span></button>})}</div><div className="mt-5 text-xs font-bold uppercase text-slate-500">Recent movements</div><div className="mt-2 max-h-64 space-y-2 overflow-auto">{recent.map(m=>{const d=data(m)!;const effect=d.sealedOpenEffect||d.sealedOpenAfter;return <div key={m.id} className="rounded-lg bg-slate-950 p-3 text-xs"><div className="flex justify-between gap-2"><b>{String(d.movementType)}</b><span>{Number(d.quantityDelta)>0?'+':''}{Number(d.quantityDelta).toLocaleString()} {String(d.baseUnit||'')}</span></div>{effect&&<div className="mt-1 text-amber-200">{Number(effect.sealedContainersBefore??effect.sealedContainers??0)} → {Number(effect.sealedContainersAfter??effect.sealedContainers??0)} sealed · {Number(effect.openQuantityBefore??effect.openQuantity??0).toLocaleString()} → {Number(effect.openQuantityAfter??effect.openQuantity??0).toLocaleString()} ml open</div>}<div className="mt-1 text-slate-500">{String(d.reason||d.reasonCode||'')}</div>{canReverseMovement&&['WASTE','TRANSFER_IN','TRANSFER_OUT'].includes(String(d.movementType))&&<button className={button} onClick={()=>setReversing(m)}>Correct mistake ? Reverse recording</button>}</div>})}</div></>:<p className="text-sm text-slate-500">No stock items.</p>}</aside>
  </div>
   <WebStockCountHistory records={records}/>
   {reversing&&<Modal title="Reverse inventory recording" onClose={()=>setReversing(null)}><WebMovementReversalDialog records={records} movement={reversing} command={command} onClose={()=>setReversing(null)}/></Modal>}
   {physicalCount&&<WebPhysicalCountDialog records={records} scope={physicalCount.scope} locationId={physicalCount.locationId} command={command} onClose={()=>setPhysicalCount(null)}/>}
   {batchOpen&&<Modal title="Prepare a recipe batch" onClose={()=>setBatchOpen(false)}><WebBatchPreparationForm products={products} stocks={stocks} locations={locations} disabled={disabled} onClose={()=>setBatchOpen(false)} onSubmit={async payload=>{const target=String(payload.outputStockItemId||'');const outcome=await command('inventory.produceBatch','stockItems',target,{id:target,...payload});setCommandNotice(outcomeMessage(outcome,'Batch preparation'));if(isCommandConfirmed(outcome))setBatchOpen(false);return outcome}}/></Modal>}
   {modal&&<Modal title={modal==='ADJUST'?'Correct stock balance':modal==='TRANSFER'?'Transfer stock':'Record waste'} onClose={()=>setModal(null)}>
    <div className="space-y-3">
     {commandNotice&&<p role="status" className="rounded-lg border border-slate-700 bg-slate-900 p-3 text-sm">{commandNotice}</p>}
     <label className="block text-sm">Stock item<select className={field} value={form.stockItemId} onChange={event=>{const stockId=event.target.value;const stock=stocks.find(item=>item.id===stockId);const balance=stock?sealedOpenBalance(stock,form.locationId):null;const quantity=Number(data(stock)?.currentStock?.[form.locationId]||0);setForm({...form,stockItemId:stockId,countedQty:quantity,expectedQuantity:quantity,expectedBaseUnit:String(data(stock)?.baseUnit||''),expectedSealedContainerSize:Number(data(stock)?.sealedContainerSize||0),expectedSealedContainers:balance?.sealed??null,expectedOpenQuantity:balance?.open??null,sealedContainers:balance?.sealed??0,openQuantity:balance?.open??0})}}>{stocks.map(stock=><option key={stock.id} value={stock.id}>{String(data(stock)?.name)}</option>)}</select></label>
     <label className="block text-sm">Location<select className={field} value={form.locationId} onChange={event=>{const locationId=event.target.value;const stock=stocks.find(item=>item.id===form.stockItemId);const balance=stock?sealedOpenBalance(stock,locationId):null;const quantity=Number(data(stock)?.currentStock?.[locationId]||0);setForm({...form,locationId,toLocationId:locations.find(item=>item.id!==locationId)?.id||'',countedQty:quantity,expectedQuantity:quantity,expectedBaseUnit:String(data(stock)?.baseUnit||''),expectedSealedContainerSize:Number(data(stock)?.sealedContainerSize||0),expectedSealedContainers:balance?.sealed??null,expectedOpenQuantity:balance?.open??null,sealedContainers:balance?.sealed??0,openQuantity:balance?.open??0})}}>{locations.map(location=><option key={location.id} value={location.id}>{String(data(location)?.name)}</option>)}</select></label>
     {modal==='TRANSFER'&&<label className="block text-sm">Destination<select className={field} value={form.toLocationId} onChange={event=>setForm({...form,toLocationId:event.target.value})}>{locations.filter(location=>location.id!==form.locationId).map(location=><option key={location.id} value={location.id}>{String(data(location)?.name)}</option>)}</select></label>}
     {modal==='ADJUST'?adjustmentBreakdownRequired?<><div className="rounded-lg border border-amber-600/30 bg-amber-500/5 p-3 text-sm">Reviewed balance: {adjustmentSealedBalance?adjustmentSealedBalance.sealed+' sealed · '+adjustmentSealedBalance.open+' ml open':'Sealed/open balance is not reconciled'}<br/>Corrected equivalent: {(Number(form.sealedContainers||0)*adjustmentSize+Number(form.openQuantity||0)).toLocaleString()} ml</div><div className="grid gap-3 sm:grid-cols-2"><label className="block text-sm">Correct sealed bottles<input type="number" min="0" step="1" className={field} value={form.sealedContainers} onChange={event=>setForm({...form,sealedContainers:Number(event.target.value)})}/></label><label className="block text-sm">Open liquid (ml)<input type="number" min="0" max={Math.max(0,adjustmentSize-0.000001)} step="0.1" className={field} value={form.openQuantity} onChange={event=>setForm({...form,openQuantity:Number(event.target.value)})}/></label></div>{adjustmentBreakdownInvalid&&<p role="alert" className="text-sm text-rose-200">Enter whole sealed bottles and less than {adjustmentSize} ml in the open bottle.</p>}</>:<><div className="grid grid-cols-2 gap-2"><Fact label="Reviewed balance" value={Number(form.expectedQuantity||0).toLocaleString()+' '+String(form.expectedBaseUnit||'')}/><Fact label="Change" value={(Number(form.countedQty)-Number(form.expectedQuantity||0)).toLocaleString()+' '+String(form.expectedBaseUnit||'')}/></div><label className="block text-sm">Corrected physical balance<input type="number" min="0" step="0.001" className={field} value={form.countedQty} onChange={event=>{try{setForm({...form,countedQty:parseQuantity(event.target.value)})}catch{}}}/></label></>:<><label className="block text-sm">Physical stock<select className={field} value={form.disposition||'SEALED'} onChange={event=>setForm({...form,disposition:event.target.value})}><option value="SEALED">Sealed containers (where configured)</option><option value="OPEN">Open liquid / base units</option></select></label><label className="block text-sm">Quantity<input type="number" min="0.001" step="0.001" className={field} value={form.quantity} onChange={event=>setForm({...form,quantity:event.target.value})}/></label></>}
     <label className="block text-sm">Reason / review note<textarea className={field} value={form.reason} onChange={event=>setForm({...form,reason:event.target.value})}/></label>
     <button disabled={disabled||!String(form.reason||'').trim()||!form.stockItemId||modal==='ADJUST'&&adjustmentBreakdownInvalid||(modal==='TRANSFER'||modal==='WASTE')&&(!Number.isFinite(Number(form.quantity))||Number(form.quantity)<=0||modal==='TRANSFER'&&!form.toLocationId)} className={primary} onClick={()=>void(modal==='ADJUST'?commitAdjustment():commit())}>{modal==='ADJUST'?'Post correction':'Review and confirm'}</button>
    </div>
   </Modal>}

 </section>;
}

function WebBatchPreparationForm({products,stocks,locations,disabled,onClose,onSubmit}:{products:BusinessRecord[];stocks:BusinessRecord[];locations:BusinessRecord[];disabled:boolean;onClose:()=>void;onSubmit:(payload:Record<string,unknown>)=>Promise<CommandOutcome>}){
 const [reviewed]=useState(()=>[...products,...stocks,...locations]);
 const recipes=products.filter(product=>data(product)?.inventoryType==='BATCH'&&typeof data(product)?.stockItemId==='string'&&data(product)?.stockItemId&&Array.isArray(data(product)?.recipeIngredients)&&data(product)!.recipeIngredients.length>0);
 const [recipeProductId,setRecipeProductId]=useState(recipes[0]?.id||'');const [locationId,setLocationId]=useState(locations[0]?.id||'');const [batchCount,setBatchCount]=useState(1);const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
 const recipe=recipes.find(product=>product.id===recipeProductId);const recipeData=data(recipe);const ingredients=Array.isArray(recipeData?.recipeIngredients)?recipeData.recipeIngredients:[];const linkedOutputId=String(recipeData?.stockItemId||'');const eligible=stocks.filter(stock=>stock.id===linkedOutputId&&['piece','portion'].includes(String(data(stock)?.baseUnit||'piece').toLowerCase()));const output=eligible.find(stock=>stock.id===linkedOutputId);const yieldPerBatch=Number(recipeData?.recipeYield||0);const outputCount=yieldPerBatch*batchCount;
 const submit=async(event:React.FormEvent)=>{event.preventDefault();setError('');if(!recipe||!output||!locationId||!Number.isInteger(batchCount)||batchCount<1||batchCount>1000||reason.trim().length<3)return;setBusy(true);try{const outcome=await onSubmit({recipeProductId,outputStockItemId:linkedOutputId,locationId,batchCount,reason:reason.trim(),...inventoryRevisions(reviewed,[linkedOutputId,...ingredients.map((line:any)=>String(line.stockItemId))],[locationId],[recipeProductId])});if(!isCommandConfirmed(outcome))setError(`${outcomeMessage(outcome,'Batch preparation')} Keep this form open and review Activity before retrying.`)}catch(cause){setError(operatorError(cause))}finally{setBusy(false)}};
 return <form className="max-h-[70vh] space-y-3 overflow-y-auto" onSubmit={event=>void submit(event)}>{!recipes.length?<p className="rounded-lg border border-amber-600/30 bg-amber-500/5 p-3 text-sm">No saved Batch recipe is available. Create a Batch recipe in Catalog first.</p>:<>
  <label className="block text-sm">Batch recipe<select className={field+' mt-1'} value={recipeProductId} onChange={event=>setRecipeProductId(event.target.value)}>{recipes.map(item=><option key={item.id} value={item.id}>{String(data(item)?.name||item.id)}</option>)}</select></label>
  <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 text-sm"><b>Finished portions stock</b><p className="mt-1">{output?`${String(data(output)?.name)} · ${String(data(output)?.baseUnit)}`:'Linked output stock must use piece or portion units.'}</p><p className="mt-1 text-xs text-slate-500">POS deducts prepared portions from this linked stock. The saved recipe ingredients are consumed here during preparation.</p></div>
  <label className="block text-sm">Storage place<select className={field+' mt-1'} value={locationId} onChange={event=>setLocationId(event.target.value)}><option value="">Choose storage place</option>{locations.map(item=><option key={item.id} value={item.id}>{String(data(item)?.name||item.id)}</option>)}</select></label>
  <label className="block text-sm">Number of batches<input className={field+' mt-1'} type="number" min="1" max="1000" step="1" value={batchCount} onChange={event=>setBatchCount(Number(event.target.value))}/></label>
  <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 text-sm"><b>Preparation preview</b><p className="mt-1">{String(recipeData?.name||'Recipe')} yields {yieldPerBatch||'—'} portions per batch; this makes {outputCount||'—'} {String(data(output)?.baseUnit||'portions')}.</p><div className="mt-2 space-y-1 text-xs text-slate-400">{ingredients.map((line:any)=><p key={line.stockItemId}>{String(data(stocks.find(item=>item.id===line.stockItemId))?.name||line.stockItemId)}: {(Number(line.quantity)*yieldPerBatch*batchCount).toLocaleString()} {String(data(stocks.find(item=>item.id===line.stockItemId))?.baseUnit||'units')}</p>)}</div><p className="mt-2 text-xs text-slate-500">Ingredient consumption and finished stock commit together on the server. This action is online-only; offline work remains a draft.</p></div>
  <label className="block text-sm">Preparation note<input required minLength={3} maxLength={180} className={field+' mt-1'} value={reason} onChange={event=>setReason(event.target.value)}/></label>
 </>}{error&&<p role="alert" className="text-sm text-rose-200">{error}</p>}<div className="flex justify-end gap-2"><button type="button" className={button} onClick={onClose}>Close</button><button type="submit" disabled={disabled||busy||!recipe||!output||!locationId||reason.trim().length<3} className={primary}>{busy?'Preparing…':'Prepare batch'}</button></div></form>;
}

 const Panel=({title,children}:{title:string;children:React.ReactNode})=><section className="rounded-xl border border-slate-800 bg-slate-900/40 p-4"><h3 className="mb-3 font-bold">{title}</h3><div className="space-y-2">{children}</div></section>;
const Metric=({icon,label,value}:{icon:React.ReactNode;label:string;value:string})=><div className="rounded-xl border border-slate-800 bg-slate-900 p-4"><div className="flex items-center gap-2 text-xs uppercase text-slate-500">{icon}{label}</div><div className="mt-2 text-2xl font-black">{value}</div></div>;
const Fact=({label,value}:{label:string;value:string})=><div className="rounded-lg bg-slate-950 p-3"><div className="text-[10px] uppercase text-slate-600">{label}</div><div className="font-semibold">{value}</div></div>;
const Restore=({label,disabled,onRestore}:{record:BusinessRecord;label:string;disabled:boolean;onRestore:()=>Promise<void>})=><div className="flex items-center justify-between rounded-lg bg-slate-950 p-2 text-sm"><span>{label}</span><button disabled={disabled} className={button} onClick={()=>void onRestore()}>Reactivate</button></div>;
const Modal=({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode})=><Dialog title={title} onClose={onClose}>{children}</Dialog>;
